INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('8a0288be-5e14-5257-aa18-871f368f2051', 'b5d63c4f-1cb7-5974-a758-eb342d3ba563', 'published', 'Domwood Lamello', 'PL', NULL, NULL, 'Sauna ogrodowa Lamello dla 5 osób: prosta, nowoczesna bryła z naturalnym drewnem, pionowa elewacja lamelowa, duże przeszklenie i zadaszona wnęka wejściowa. Piec elektryczny Harvia 8 kW, wnętrze z lipową boazerią i ławkami z olchy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '315 x 210 cm (wnętrze 200 x 174 cm)', 'Blacha trapezowa w kolorze antracytowym', 'Prefabrykowany moduł drewniany produkowany w całości w hali, dostarczany w całości. Konstrukcja z drewna C24 (świerk skandynawski, kantówka 45 x 95 mm), ocieplenie twardą wełną 10 cm w podłodze, ścianach i dachu, od zewnątrz płyta bitumowana Steico Black 22 mm i elewacja z pionowych drewnianych lamel na pióro i wpust zabezpieczonych lazurą Remmers.', 'Przygotowanie podłoża po stronie klienta; rozładunek (dźwig, HDS lub wózek widłowy o odpowiednim udźwigu) organizuje inwestor', 'Na życzenie wersja w lustrzanym odbiciu, piec opalany drewnem lub piec elektryczny sterowany telefonem; konfigurację i cenę wybranych zmian ustala się indywidualnie.', 'EUR', NULL, NULL, false, '2026-10-30T14:16:13.482Z'::timestamptz, '2026-10-30T19:40:57.487Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Szkło hartowane w pakiecie dwuszybowym","benchMaterial":"Olcha (ławki i oparcie)","insulationType":"Twarda wełna 10 cm w podłodze, ścianach i dachu; od wewnątrz folia aluminiowa do saun","hasChangingArea":false,"seatingCapacity":5,"claddingMaterial":"Deska lamelowa grubości 2 cm na pióro i wpust, lazura Remmers; pod spodem płyta bitumowana Steico Black 22 mm","interiorWoodType":"Bezsęczna boazeria lipowa","electricalRequirement":"Piec elektryczny Harvia 8 kW z opóźnionym startem do 8 godzin; oświetlenie RGB z pilotem; oświetlenie zewnętrzne z czujnikiem zmierzchu"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'domwood-lamello', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
