e inwestor', NULL, 'EUR', NULL, NULL, false, '2026-10-30T14:06:09.880Z'::timestamptz, '2026-10-30T19:40:54.572Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Okno trzyszybowe hartowane 190 x 190 cm; drzwi zewnętrzne szklane z pochwytem","benchMaterial":"Olcha (nienagrzewająca się), ławki na dwóch poziomach","insulationType":"Wełna 10 cm w podłodze i ścianach, wewnątrz ściany wyłożone folią aluminiową","hasChangingArea":false,"seatingCapacity":5,"claddingMaterial":"Deska świerkowa skandynawska 19x146 mm malowana lazurą Remmers; tylna ściana z blachy trapezowej T18+","interiorWoodType":"Boazeria lipowa lub z thermo sosny (do wyboru)","electricalRequirement":"Piec Harvia PC110 10,8 kW z zewnętrznym sterownikiem WiFi SaunaBox; skrzynka z bezpiecznikami na bocznej ścianie"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'domwood-modern-barn', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
