estor', 'Sauna konfigurowana zgodnie z oczekiwaniami klienta; dostępne możliwości wykonania i dopasowania wybranych elementów ustala się indywidualnie.', 'EUR', NULL, NULL, false, '2026-10-30T14:16:19.396Z'::timestamptz, '2026-10-30T19:40:59.408Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Duże okno z hartowanego szkła w pakiecie dwuszybowym z zewnętrzną przesuwną osłoną lamelową; drzwi do części saunowej ze szkła hartowanego","benchMaterial":"Olcha (dwupoziomowe ławki i oparcie); ławka świerkowa w przedsionku","insulationType":"Twarda wełna 10 cm w podłodze, ścianach i dachu; od wewnątrz folia aluminiowa do saun","hasChangingArea":true,"seatingCapacity":6,"claddingMaterial":"Deska lamelowa grubości 2 cm na pióro i wpust, lazura Remmers; pod spodem płyta bitumowana Steico Black 22 mm","interiorWoodType":"Bezsęczna boazeria lipowa (część saunowa), boazeria świerkowa (przedsionek)","electricalRequirement":"Piec opalany drewnem Stoveman (bez pieca elektrycznego); zasilanie dla oświetlenia RGB z pilotem i oświetlenia zewnętrznego z czujnikiem zmierzchu","changingAreaDescription":"Osobny przedsionek z boazerią świerkową, ławką, 6 wieszakami i płytkami ceramicznymi na podłodze"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'domwood-lamello-firestone', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('d5e91d88-542d-5e29-a19e-5b47c1439038', 'b5d63c4f-1cb7-5974-a758-eb342d3ba563', 'published', 'Domwood Lamello Big', 'PL', NULL, NULL, 'Rozbudowana sauna ogrodowa dla 5-6 osób: ciemna elewacja z pionowych lamelek, duże frontowe przeszklenie, dekoracyjne oświetlenie oraz osobny przedsionek z prysznicem. Piec Harvia PC90, system audio z głośnikami JBL.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '370 x 245 cm', 'Blacha trapezowa w kolorze antracytowym', 'Prefabrykowany moduł drewniany produkowany w całości w hali, dostarczany w całości. Konstrukcja z drewna C24 (świerk skandynawski, kantówka 45 x 95 mm), ocieplenie twardą wełną 10 cm w podłodze, ścianach i dachu, od zewnątrz płyta bitumowana Steico Black 22 mm i elewacja z pionowych drewnianych lamel na pióro i wpust zabezpieczonych lazurą Remmers.', 'Przygotowanie podłoża po stronie klienta; rozładunek (dźwig, HDS lub wózek widłowy o odpowiednim udźwigu) organizuje inwestor', 'Możliwość wyboru innego pieca oraz bojlera do strefy prysznicowej; szczegóły konfiguracji i zmiany wyposażenia uzgadnia się indywidualnie przy zamówieniu.', 'EUR', NULL, NULL, false, '2026-10-30T14:16:25.002Z'::timestamptz, '2026-10-30T19:41:01.041Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Okno ze szkła hartowanego w pakiecie dwuszybowym; drzwi do sauny ze szkła hartowanego","benchMaterial":"Olcha (ławki i oparcia)","insulationType":"Twarda wełna 10 cm w podłodze, ścianach i dachu; od wewnątrz folia aluminiowa do saun","hasChangingArea":true,"seatingCapacity":5,"claddingMaterial":"Pionowe drewniane lamelki na pióro i wpust, lazura Remmers; pod spodem płyta bitumowana Steico Black 22 mm","interiorWoodType":"Bezsęczna boazeria lipowa","electricalRequirement":"Piec elektryczny Harvia PC90 (możliwość wyboru innego pieca); oświetlenie RGB z pilotem; audio JBL ze sterowaniem Dexon; bojler do prysznica; wentylacja mechaniczna z czujnikiem wilgoci","changingAreaDescription":"Wydzielony przedsionek z prysznicem z deszczownicą, 6 wieszakami i płytkami ceramicznymi"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'domwood-lamello-big', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('c69393dd-aef1-4c86-92a7-4347cb30b2e5', '8a0288be-5e14-5257-aa18-871f368f2051', 'en', NULL, 'Lamello garden sauna for 5 people: a simple, modern body with natural wood, a vertical slat facade, large glazing and a covered entrance niche. Harvia 8 kW electric heater, interior with linden paneling and alder benches.', '2026-10-30T14:16:13.482Z'::timestamptz, '2026-10-30T19:40:57.731Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ground preparation by the customer; unloading (crane, HIAB truck or forklift of adequate capacity) is arranged by the investor', '{"specs":{"glazingType":{"value":"Tempered glass in a double-glazed unit"},"benchMaterial":{"value":"Alder (benches and backrest)"},"insulationType":{"value":"10 cm hard wool in the floor, walls and roof; sauna aluminium foil on the inside"},"claddingMaterial":{"value":"2 cm tongue-and-groove slat boards, Remmers lazure; Steico Black 22 mm bitumen board underneath"},"interiorWoodType":{"value":"Knot-free linden paneling"},"electricalRequirement":{"value":"Harvia 8 kW electric heater with a delayed start of up to 8 hours; RGB lighting with a remote; exterior lighting with a dusk sensor"}}}'::jsonb, 'Prefabricated timber module built entirely in the workshop and delivered in one piece. C24 timber structure (Scandinavian spruce, 45 x 95 mm), 10 cm hard wool insulation in the floor, walls and roof, Steico Black 22 mm bitumen board outside and a facade of vertical tongue-and-groove wooden slats protected with Remmers lazure.', 'Trapezoidal sheet metal in anthracite', 'On request: a mirrored version, a wood-fired heater or an electric heater controlled by phone; the configuration and the price of selected changes are agreed individually.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('6e0ec622-dedd-4e11-bfd6-86222d438698', '8a0288be-5e14-5257-aa18-871f368f2051', 'de', NULL, 'Gartensauna Lamello für 5 Personen: schlichter, moderner Baukörper mit Naturholz, senkrechte Lamellenfassade, große Verglasung und überdachte Eingangsnische. Elektrischer Harvia-Ofen 8 kW, Innenraum mit Lindenverkleidung und Erlenbänken.', '2026-10-30T14:16:13.482Z'::timestamptz, '2026-10-30T19:40:57.731Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Untergrundvorbereitung durch den Kunden; das Abladen (Kran, HDS oder Gabelstapler mit ausreichender Tragkraft) organisiert der Bauherr', '{"specs":{"glazingType":{"value":"Gehärtetes Glas als Zweifachverglasung"},"benchMaterial":{"value":"Erle (Bänke und Rückenlehne)"},"insulationType":{"value":"10 cm harte Wolle in Boden, Wänden und Dach; innen Sauna-Aluminiumfolie"},"claddingMaterial":{"value":"Lamellenbretter 2 cm mit Nut und Feder, Remmers-Lasur; darunter Steico-Black-Bitumenplatte 22 mm"},"interiorWoodType":{"value":"Astfreie Wandverkleidung aus Linde"},"electricalRequirement":{"value":"Elektrischer Harvia-Ofen 8 kW mit verzögertem Start bis 8 Stunden; RGB-Beleuchtung mit Fernbedienung; Außenbeleuchtung mit Dämmerungssensor"}}}'::jsonb, 'Vorgefertigtes Holzmodul, vollständig in der Halle gefertigt und im Ganzen geliefert. Konstruktion aus C24-Holz (skandinavische Fichte, Kantholz 45 x 95 mm), 10 cm harte Wolldämmung in Boden, Wänden und Dach, außen Steico-Black-Bitumenplatte 22 mm und Fassade aus senkrechten Holzlamellen mit Nut und Feder, mit Remmers-Lasur geschützt.', 'Trapezblech in Anthrazit', 'Auf Wunsch: spiegelverkehrte Ausführung, holzbefeuerter Ofen oder per Telefon gesteuerter Elektroofen; Konfiguration und Preis ausgewählter Änderungen werden individuell vereinbart.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('05adb6ca-b0f7-4044-acda-924bc03afa38', '8a0288be-5e14-5257-aa18-871f368f2051', 'nl', NULL, 'Tuinsauna Lamello voor 5 personen: een eenvoudig, modern volume met natuurlijk hout, een gevel van verticale lamellen, grote beglazing en een overdekte ingangsnis. Elektrische Harvia-kachel van 8 kW, interieur met lindehouten wandbekleding en elzenbanken.', '2026-10-30T14:16:13.482Z'::timestamptz, '2026-10-30T19:40:57.731Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Voorbereiding van de ondergrond door de klant; het lossen (kraan, laadkraan of vorkheftruck met voldoende hefvermogen) wordt door de opdrachtgever geregeld', '{"specs":{"glazingType":{"value":"Gehard glas in een dubbele beglazing"},"benchMaterial":{"value":"Els (banken en rugleuning)"},"insulationType":{"value":"10 cm harde wol in vloer, wanden en dak; aan de binnenzijde sauna-aluminiumfolie"},"claddingMaterial":{"value":"Lamellenplanken van 2 cm met messing en groef, Remmers-lazuur; eronder Steico Black bitumenplaat 22 mm"},"interiorWoodType":{"value":"Kwastvrije lindehouten wandbekleding"},"electricalRequirement":{"value":"Elektrische Harvia-kachel van 8 kW met vertraagde start tot 8 uur; RGB-verlichting met afstandsbediening; buitenverlichting met schemerschakelaar"}}}'::jsonb, 'Geprefabriceerde houten module, volledig in de werkplaats gebouwd en in één stuk geleverd. C24-houtconstructie (Scandinavisch vuren, regel 45 x 95 mm), 10 cm harde wolisolatie in vloer, wanden en dak, aan de buitenzijde Steico Black bitumenplaat 22 mm en een gevel van verticale houten lamellen met messing en groef, beschermd met Remmers-lazuur.', 'Trapeziumplaat in antraciet', 'Op verzoek: een gespiegelde uitvoering, een houtgestookte kachel of een elektrische kachel die met de telefoon wordt bediend; de configuratie en de prijs van gekozen wijzigingen worden individueel afgesproken.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('cc615be7-dc24-4880-bd81-eda44911af11', '8c198fe2-907a-559c-a31f-702314c6fd08', 'en', NULL, 'A modern garden sauna in the Modern Barn style: Scandinavian design, a single-slope roof with a wide overhang, large glazing and a terrace. Built entirely in the producer''s workshop and delivered as a ready-made module.', '2026-10-30T14:06:09.880Z'::timestamptz, '2026-10-30T19:40:54.832Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ground preparation by the customer; unloading (crane, HIAB truck or forklift of adequate capacity) is arranged by the investor', '{"specs":{"glazingType":{"value":"Triple-glazed tempered window 190 x 190 cm; glass exterior door with a handle bar"},"benchMaterial":{"value":"Alder (does not heat up), benches on two levels"},"insulationType":{"value":"10 cm wool in the floor and walls, walls lined with aluminium foil on the inside"},"claddingMaterial":{"value":"Scandinavian spruce boards 19x146 mm finished with Remmers lazure; rear wall of T18+ trapezoidal sheet metal"},"interiorWoodType":{"value":"Linden or thermo pine paneling (to choose from)"},"electricalRequirement":{"value":"Harvia PC110 10.8 kW heater with an external SaunaBox WiFi controller; fuse box on the side wall"}}}'::jsonb, 'Prefabricated timber module built entirely in the workshop and delivered in one piece. 45x95 mm C24 frame, 10 cm wool insulation (floor and walls), facade of 19x146 mm Scandinavian spruce boards finished with Remmers lazure, rear wall of T18+ trapezoidal sheet metal.', 'Single-slope, trapezoidal sheet metal; overhang of 90 cm at the front and 30 cm on the sides, spruce soffit boards', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('a3e967c2-722a-45a3-b39a-1337446e461f', '8c198fe2-907a-559c-a31f-702314c6fd08', 'de', NULL, 'Moderne Gartensauna im Modern-Barn-Stil: skandinavisches Design, Pultdach mit weitem Dachüberstand, große Verglasung und Terrasse. Vollständig in der Halle des Herstellers gefertigt und als fertiges Modul geliefert.', '2026-10-30T14:06:09.880Z'::timestamptz, '2026-10-30T19:40:54.832Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Untergrundvorbereitung durch den Kunden; das Abladen (Kran, HDS oder Gabelstapler mit ausreichender Tragkraft) organisiert der Bauherr', '{"specs":{"glazingType":{"value":"Dreifach verglastes gehärtetes Fenster 190 x 190 cm; gläserne Außentür mit Haltegriff"},"benchMaterial":{"value":"Erle (heizt sich nicht auf), Bänke auf zwei Ebenen"},"insulationType":{"value":"10 cm Wolle in Boden und Wänden, Wände innen mit Aluminiumfolie ausgekleidet"},"claddingMaterial":{"value":"Skandinavische Fichtenbretter 19x146 mm mit Remmers-Lasur; Rückwand aus Trapezblech T18+"},"interiorWoodType":{"value":"Wandverkleidung aus Linde oder Thermokiefer (zur Wahl)"},"electricalRequirement":{"value":"Harvia-Ofen PC110 10,8 kW mit externer WiFi-Steuerung SaunaBox; Sicherungskasten an der Seitenwand"}}}'::jsonb, 'Vorgefertigtes Holzmodul, vollständig in der Halle gefertigt und im Ganzen geliefert. Rahmen 45x95 mm C24, 10 cm Wolldämmung (Boden und Wände), Fassade aus skandinavischen Fichtenbrettern 19x146 mm mit Remmers-Lasur, Rückwand aus Trapezblech T18+.', 'Pultdach, Trapezblech; Dachüberstand 90 cm vorne und 30 cm an den Seiten, Untersicht aus Fichtenbrettern', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('ec665eb8-5849-4b14-b6dd-9024c965f7c3', '8c198fe2-907a-559c-a31f-702314c6fd08', 'nl', NULL, 'Moderne tuinsauna in Modern Barn-stijl: Scandinavisch design, een lessenaarsdak met brede overstek, grote beglazing en een terras. Volledig in de werkplaats van de producent gebouwd en als kant-en-klare module geleverd.', '2026-10-30T14:06:09.880Z'::timestamptz, '2026-10-30T19:40:54.832Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Voorbereiding van de ondergrond door de klant; het lossen (kraan, laadkraan of vorkheftruck met voldoende hefvermogen) wordt door de opdrachtgever geregeld', '{"specs":{"glazingType":{"value":"Gehard drievoudig glazen raam 190 x 190 cm; glazen buitendeur met handgreep"},"benchMaterial":{"value":"Els (wordt niet heet), banken op twee niveaus"},"insulationType":{"value":"10 cm wol in vloer en wanden, wanden aan de binnenzijde bekleed met aluminiumfolie"},"claddingMaterial":{"value":"Scandinavische vurenplanken 19x146 mm met Remmers-lazuur; achterwand van trapeziumplaat T18+"},"interiorWoodType":{"value":"Wandbekleding van linde of thermo-grenen (naar keuze)"},"electricalRequirement":{"value":"Harvia PC110 10,8 kW kachel met externe WiFi-besturing SaunaBox; zekeringkast op de zijwand"}}}'::jsonb, 'Geprefabriceerde houten module, volledig in de werkplaats gebouwd en in één stuk geleverd. Frame 45x95 mm C24, 10 cm wolisolatie (vloer en wanden), gevel van Scandinavische vurenplanken 19x146 mm met Remmers-lazuur, achterwand van trapeziumplaat T18+.', 'Lessenaarsdak, trapeziumplaat; overstek van 90 cm aan de voorkant en 30 cm aan de zijkanten, onderbetimmering van vurenplanken', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b052ecb0-4dab-45a9-8dc5-da5e0656cee1', '7d2f364b-7a0f-5e7b-aca2-10d98cabedff', 'en', NULL, 'Bold Forest garden sauna: bold design, a deep green front with double LED backlighting, side facade of diagonally laid thermo pine, two-level benches and a large window. Built entirely in the producer''s workshop and delivered as a ready-made module.', '2026-10-30T14:16:10.076Z'::timestamptz, '2026-10-30T19:40:56.030Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ground preparation by the customer; unloading (crane, HIAB truck or forklift of adequate capacity) is arranged by the investor', '{"specs":{"glazingType":{"value":"Fixed window 70 x 190 cm of tempered glass; glass exterior door with a handle bar"},"benchMaterial":{"value":"Alder (does not heat up), benches on two levels"},"insulationType":{"value":"10 cm wool in the floor and walls, walls lined with aluminium foil on the inside"},"claddingMaterial":{"value":"Thermo pine 19x142 mm; rear wall of T18+ trapezoidal sheet metal"},"interiorWoodType":{"value":"Alder or thermo pine paneling (to choose from)"},"electricalRequirement":{"value":"Harvia PC110e 10.8 kW heater with an external SaunaBox WiFi controller; fuse box on the rear wall"}}}'::jsonb, 'Prefabricated timber module built entirely in the workshop and delivered in one piece. 45x95 mm C24 frame, 10 cm wool insulation (floor and walls), facade of 19x142 mm thermo pine, rear wall of T18+ trapezoidal sheet metal.', 'Single-slope, trapezoidal sheet metal; overhang of 30 cm at the front, thermo pine soffit boards 19x142 mm', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('dc1961d2-5397-42b2-828f-480ca94ac03f', '7d2f364b-7a0f-5e7b-aca2-10d98cabedff', 'de', NULL, 'Gartensauna Bold Forest: mutiges Design, tiefgrüne Front mit doppelter LED-Hinterleuchtung, Seitenfassade aus schräg verlegter Thermokiefer, zweistufige Bänke und großes Fenster. Vollständig in der Halle des Herstellers gefertigt und als fertiges Modul geliefert.', '2026-10-30T14:16:10.076Z'::timestamptz, '2026-10-30T19:40:56.030Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Untergrundvorbereitung durch den Kunden; das Abladen (Kran, HDS oder Gabelstapler mit ausreichender Tragkraft) organisiert der Bauherr', '{"specs":{"glazingType":{"value":"Festes Fenster 70 x 190 cm aus gehärtetem Glas; gläserne Außentür mit Haltegriff"},"benchMaterial":{"value":"Erle (heizt sich nicht auf), Bänke auf zwei Ebenen"},"insulationType":{"value":"10 cm Wolle in Boden und Wänden, Wände innen mit Aluminiumfolie ausgekleidet"},"claddingMaterial":{"value":"Thermokiefer 19x142 mm; Rückwand aus Trapezblech T18+"},"interiorWoodType":{"value":"Wandverkleidung aus Erle oder Thermokiefer (zur Wahl)"},"electricalRequirement":{"value":"Harvia-Ofen PC110e 10,8 kW mit externer WiFi-Steuerung SaunaBox; Sicherungskasten an der Rückwand"}}}'::jsonb, 'Vorgefertigtes Holzmodul, vollständig in der Halle gefertigt und im Ganzen geliefert. Rahmen 45x95 mm C24, 10 cm Wolldämmung (Boden und Wände), Fassade aus Thermokiefer 19x142 mm, Rückwand aus Trapezblech T18+.', 'Pultdach, Trapezblech; Dachüberstand 30 cm vorne, Untersicht aus Thermokiefer 19x142 mm', NULL, NULL) ON CONFLICT DO NOTHING;
