', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('676f9d78-8af3-4a99-b807-d71fbd507bed', '3e6ba1b2-373c-56ee-aa76-2938905802da', 'en', NULL, 'A compact garden sauna in the Modern Barn style for limited space: a natural wood front combined with dark sheet metal on the side walls and roof, glazed door with a long handle bar and two-level benches.', '2026-10-30T14:16:11.010Z'::timestamptz, '2026-10-30T19:40:56.537Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ground preparation by the customer; unloading (crane, HIAB truck or forklift of adequate capacity) is arranged by the investor', '{"specs":{"glazingType":{"value":"Glass exterior door with a handle bar"},"benchMaterial":{"value":"Alder (does not heat up), benches on two levels"},"insulationType":{"value":"10 cm wool in the floor and walls, walls lined with aluminium foil on the inside"},"claddingMaterial":{"value":"Front: Scandinavian spruce boards 19x146 mm finished with Remmers lazure; side walls of T18+ trapezoidal sheet metal"},"interiorWoodType":{"value":"Linden or thermo pine paneling (to choose from)"},"electricalRequirement":{"value":"Harvia SW60e 6 kW heater with an external SaunaBox WiFi controller; fuse box on the rear wall"}}}'::jsonb, 'Prefabricated timber module built entirely in the workshop and delivered in one piece. 45x95 mm C24 frame, 10 cm wool insulation (floor and walls), front facade of 19x146 mm Scandinavian spruce boards finished with Remmers lazure, side walls of T18+ trapezoidal sheet metal.', 'Single-slope, trapezoidal sheet metal; overhang of 50 cm at the front, 30 cm on the sides and 15 cm at the back, Scandinavian spruce soffit boards', NULL, NULL) ON CONFLICT DO NOTHING;
